import math
import random

class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.opponent_id = None
        self.cooperation_history = {}
        self.defection_history = {}
        self.total_interactions = {}
        self.my_coop_count = 0
        self.my_defect_count = 0
        self.round_num = 0
        self.partner_coop_count = {}
        self.partner_defect_count = {}
        self.reputation = {}
        self.trust_scores = {}
        self.epsilon = 0.05

    def decide(self) -> bool:
        self.round_num += 1
        opponent = self._ctx_opponent_id if hasattr(self, '_ctx_opponent_id') else None
        if opponent is None:
            return True

        # Initialize opponent stats if new
        if opponent not in self.cooperation_history:
            self.cooperation_history[opponent] = 0
            self.defection_history[opponent] = 0
            self.total_interactions[opponent] = 0
            self.partner_coop_count[opponent] = 0
            self.partner_defect_count[opponent] = 0
            self.trust_scores[opponent] = 0.5

        # Get opponent's reputation based on observed behavior
        opp_reputation = self._get_reputation(opponent)

        # My history with this opponent
        my_interactions = self.total_interactions.get(opponent, 0)
        my_coop = self.cooperation_history.get(opponent, 0)
        my_defect = self.defection_history.get(opponent, 0)

        # Partner's behavior towards me (if any)
        partner_coop_towards_me = self.partner_coop_count.get(opponent, 0)
        partner_defect_towards_me = self.partner_defect_count.get(opponent, 0)
        partner_total = partner_coop_towards_me + partner_defect_towards_me

        # Calculate opponent's cooperation rate towards me
        if partner_total > 0:
            partner_coop_rate = partner_coop_towards_me / partner_total
        else:
            partner_coop_rate = 0.5  # neutral

        # Learning: adapt based on interactions
        if my_interactions > 0:
            # If opponent cooperated more than 60% of time, trust increases
            if partner_total > 0 and partner_coop_rate > 0.6:
                self.trust_scores[opponent] = min(1.0, self.trust_scores[opponent] + 0.1)
            elif partner_total > 0 and partner_coop_rate < 0.4:
                self.trust_scores[opponent] = max(0.0, self.trust_scores[opponent] - 0.1)

        trust = self.trust_scores.get(opponent, 0.5)

        # Combine signals: opponent's global reputation and personal trust
        combined_trust = 0.3 * opp_reputation + 0.7 * trust

        # Deterministic threshold with occasional exploration
        if random.random() < self.epsilon:
            return random.random() < 0.5

        # Defect if opponent has bad reputation or low trust
        if combined_trust < 0.4:
            return False

        # If we've never interacted, be cautious
        if my_interactions == 0:
            return combined_trust >= 0.5

        # Strategy: Tit-for-tat with forgiveness based on reputation
        # If opponent defected last time against us, defect unless their reputation is excellent
        if partner_total > 0 and partner_defect_towards_me > partner_coop_towards_me:
            if opp_reputation > 0.8:
                return True  # forgive if good reputation
            else:
                return False

        # Default: cooperate if trust is decent
        return combined_trust >= 0.5

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        # Initialize reputation dict for all agents
        if donor_id not in self.reputation:
            self.reputation[donor_id] = {'coop': 0, 'defect': 0}
        if recipient_id not in self.reputation:
            self.reputation[recipient_id] = {'coop': 0, 'defect': 0}

        # Update donor's reputation
        if donor_action == 'cooperate':
            self.reputation[donor_id]['coop'] += 1
        else:
            self.reputation[donor_id]['defect'] += 1

        # Update recipient's reputation (they also chose an action)
        if recipient_action == 'cooperate':
            self.reputation[recipient_id]['coop'] += 1
        else:
            self.reputation[recipient_id]['defect'] += 1

        # If I'm involved, update my personal history with that opponent
        if donor_id == self.agent_id:
            opp = recipient_id
            if opp not in self.cooperation_history:
                self.cooperation_history[opp] = 0
                self.defection_history[opp] = 0
                self.total_interactions[opp] = 0
                self.partner_coop_count[opp] = 0
                self.partner_defect_count[opp] = 0
                self.trust_scores[opp] = 0.5
            if donor_action == 'cooperate':
                self.cooperation_history[opp] += 1
            else:
                self.defection_history[opp] += 1
            self.total_interactions[opp] += 1

        elif recipient_id == self.agent_id:
            opp = donor_id
            if opp not in self.cooperation_history:
                self.cooperation_history[opp] = 0
                self.defection_history[opp] = 0
                self.total_interactions[opp] = 0
                self.partner_coop_count[opp] = 0
                self.partner_defect_count[opp] = 0
                self.trust_scores[opp] = 0.5
            # Track what opponent did to me
            if donor_action == 'cooperate':
                self.partner_coop_count[opp] += 1
            else:
                self.partner_defect_count[opp] += 1
            # Track my own action towards them
            if recipient_action == 'cooperate':
                self.cooperation_history[opp] += 1
            else:
                self.defection_history[opp] += 1
            self.total_interactions[opp] += 1

        # Also track third-party actions for reputation (already done above)

    def _get_reputation(self, agent_id: int) -> float:
        if agent_id not in self.reputation:
            return 0.5
        stats = self.reputation[agent_id]
        total = stats['coop'] + stats['defect']
        if total == 0:
            return 0.5
        return stats['coop'] / total

