        self.reputation = {}
        # Track cooperation counts for each agent
        self.coop_counts = {}
        self.defect_counts = {}
        # Track outcomes with specific opponents
        self.opponent_history = {}
        # Track own recent actions for strategy adaptation
        self.own_recent = []
        # Personal forgiveness and trust levels
        self.trust_threshold = 0.2
        self.forgiveness = 0.3

    def decide(self) -> bool:
        opp = self._ctx_opponent_id
        # If no opponent info, cooperate initially
        if opp is None:
            return True
        # Calculate opponent trust score based on reputation and history
        rep = self.reputation.get(opp, 0.0)
        # Weight recent interactions more
        hist = self.opponent_history.get(opp, [])
        if hist:
            recent = hist[-5:]
            recent_score = sum(1 if a == 'cooperate' else -1 for a in recent) / len(recent)
        else:
            recent_score = 0
        # Combine reputation (global) and recent direct interactions
        trust = 0.7 * rep + 0.3 * recent_score
        # Adaptive threshold: be more forgiving if population is cooperative
        total_obs = sum(self.coop_counts.values()) + sum(self.defect_counts.values())
        if total_obs > 0:
            coop_rate = sum(self.coop_counts.values()) / total_obs
            threshold = self.trust_threshold * (1 - coop_rate * 0.5)  # lower threshold if many cooperate
        else:
            threshold = self.trust_threshold
        # If opponent is unknown, default to cooperate
        if opp not in self.reputation:
            return True
        return trust >= threshold

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        # Update own history if involved
        if donor_id == self.agent_id:
            self.own_recent.append(donor_action)
            if len(self.own_recent) > 20:
                self.own_recent.pop(0)
            # Update opponent history for this specific interaction
            opp = recipient_id
            if opp not in self.opponent_history:
                self.opponent_history[opp] = []
            self.opponent_history[opp].append(recipient_action)
            if len(self.opponent_history[opp]) > 20:
                self.opponent_history[opp].pop(0)
        elif recipient_id == self.agent_id:
            self.own_recent.append(recipient_action)
            if len(self.own_recent) > 20:
                self.own_recent.pop(0)
            # Update opponent history for donor
            opp = donor_id
            if opp not in self.opponent_history:
                self.opponent_history[opp] = []
            self.opponent_history[opp].append(donor_action)
            if len(self.opponent_history[opp]) > 20:
                self.opponent_history[opp].pop(0)

        # Update counts for all agents (including self)
        for aid, act in [(donor_id, donor_action), (recipient_id, recipient_action)]:
            if act == 'cooperate':
                self.coop_counts[aid] = self.coop_counts.get(aid, 0) + 1
            else:
                self.defect_counts[aid] = self.defect_counts.get(aid, 0) + 1

        # Update reputation based on observation (excluding self to avoid self-bias)
        if donor_id != self.agent_id:
            delta = 1.0 if donor_action == 'cooperate' else -1.0
            self.reputation[donor_id] = self.reputation.get(donor_id, 0.0) + delta * 0.1
        if recipient_id != self.agent_id:
