class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        # Reputation scores: track how often each agent cooperates
        self.coop_count = {}
        self.defect_count = {}
        # Own interaction history: opponent_id -> list of (my_action, opp_action)
        self.own_history = {}
        # Forgive/retaliate memory: track defections against me
        self.defections_against_me = 0
        self.recent_defections_against_me = []
        # Generosity factor, adjust based on overall cooperation
        self.generosity = 0.8
        # Track rounds to adapt strategy over time
        self.round_num = 0

    def decide(self) -> bool:
        opponent = getattr(self, '_ctx_opponent_id', None)
        # If no opponent, cooperate by default
        if opponent is None:
            return True

        # Calculate opponent's cooperation rate
        opp_coop = self.coop_count.get(opponent, 0)
        opp_defect = self.defect_count.get(opponent, 0)
        total_obs = opp_coop + opp_defect
        if total_obs > 0:
            coop_rate = opp_coop / total_obs
        else:
            coop_rate = 0.5  # unknown

        # Personal history with this opponent
        history = self.own_history.get(opponent, [])
        if history:
            # Last interaction with this opponent
            last_my, last_opp = history[-1]
            # If they defected last time, punish with high probability
            if last_opp == 'defect':
                # Retaliate unless generous
                if random.random() < self.generosity * 0.3:
                    return True
                else:
                    return False
            # If we cooperated and they cooperated, continue cooperating
            elif last_my == 'cooperate' and last_opp == 'cooperate':
                return True
            # If we defected and they cooperated, maybe built trust
            elif last_my == 'defect' and last_opp == 'cooperate':
                # Chance to switch to cooperation
                if random.random() < 0.7:
                    return True
                else:
                    return False
        else:
            # No history, base decision on reputation
            # If opponent has high cooperation rate, cooperate
            if coop_rate >= 0.6:
                return True
            elif coop_rate <= 0.3:
                return False
            else:
                # Uncertain, be slightly generous
                return random.random() < 0.6

        # Default fallback
        return True

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        # Update reputation counts for both actors
        if donor_action == 'cooperate':
            self.coop_count[donor_id] = self.coop_count.get(donor_id, 0) + 1
        else:
            self.defect_count[donor_id] = self.defect_count.get(donor_id, 0) + 1

        if recipient_action == 'cooperate':
            self.coop_count[recipient_id] = self.coop_count.get(recipient_id, 0) + 1
        else:
            self.defect_count[recipient_id] = self.defect_count.get(recipient_id, 0) + 1

        # If this is one of my own interactions, record it
        if donor_id == self.agent_id:
            opponent = recipient_id
            my_action = donor_action
            opp_action = recipient_action
        elif recipient_id == self.agent_id:
            opponent = donor_id
            my_action = recipient_action
            opp_action = donor_action
        else:
            return

        # Store in own history
        if opponent not in self.own_history:
            self.own_history[opponent] = []
        self.own_history[opponent].append((my_action, opp_action))
        # Keep history limited to last 10 interactions per opponent
        if len(self.own_history[opponent]) > 10:
            self.own_history[opponent] = self.own_history[opponent][-10:]

        # Track defections against me
        if opp_action == 'defect':
            self.defections_against_me += 1
            self.recent_defections_against_me.append(self.round_num)
            # Keep last 5 defection times
            if len(self.recent_defections_against_me) > 5:
                self.recent_defections_against_me.pop(0)

        # Adjust generosity based on recent defections
        if len(self.recent_defections_against_me) >= 3:
            # If being exploited, reduce generosity
            self.generosity = max(0.2, self.generosity - 0.05)
        elif self.defections_against_me == 0:
            # If never exploited, increase generosity slowly
            self.generosity = min(1.0, self.generosity + 0.01)

        # Increment round number (approximate: each observe call could be multiple, but fine)
        self.round_num += 0.5  # each joint action observed counts as half round

import math
import random


class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.reputation = {}
        self.cooperations = {}
        self.defections = {}
        self.round = 0
        self.memory = {}
        self.generation = 0
        self.my_last_actions = []
        self.opponent_history = {}
        self.victim_of_defection = set()
        self.cooperators_seen = set()
        self.defectors_seen = set()

    def decide(self) -> bool:
        opponent = self._ctx_opponent_id
        self.round += 1
        if self.round % 15 == 1:
            self.generation += 1
            self.my_last_actions = []
            self.opponent_history = {}
            self.victim_of_defection = set()
            self.cooperators_seen = set()
            self.defectors_seen = set()

        # Get reputation of opponent
        rep = self.reputation.get(opponent, 0.5)
        coop_count = self.cooperations.get(opponent, 0)
        def_count = self.defections.get(opponent, 0)
        total = coop_count + def_count

        # If we have history, use it
        if opponent in self.opponent_history:
            hist = self.opponent_history[opponent]
            if len(hist) >= 1:
                last_action = hist[-1]
                if last_action == 'defect':
                    # Defect against known defectors
                    return False
                else:
                    # If they cooperated last time, cooperate with high probability
                    if rep > 0.6:
                        return True
                    else:
                        return random.random() < 0.8

        # No direct history - use reputation
        if total > 2:
            if rep > 0.7:
                return True
            elif rep < 0.3:
                return False
            else:
                return random.random() < 0.6
        else:
            # First encounter - be cooperative but not naive
            if opponent in self.victim_of_defection:
                return False
            if opponent in self.defectors_seen:
                return False
            if opponent in self.cooperators_seen:
                return True
            # Default: cooperate with 70% probability
            return random.random() < 0.7

    def observe(
        self,
        donor_id: int,
        donor_action: str,
        recipient_id: int,
        recipient_action: str,
    ) -> None:
        # Update reputation for donor
        self._update_reputation(donor_id, donor_action)
        self._update_reputation(recipient_id, recipient_action)

        # Track cooperation/defection counts
        if donor_action == 'cooperate':
            self.cooperations[donor_id] = self.cooperations.get(donor_id, 0) + 1
        else:
            self.defections[donor_id] = self.defections.get(donor_id, 0) + 1

        if recipient_action == 'cooperate':
            self.cooperations[recipient_id] = self.cooperations.get(recipient_id, 0) + 1
        else:
            self.defections[recipient_id] = self.defections.get(recipient_id, 0) + 1

        # Track if this agent was involved
        if donor_id == self.agent_id or recipient_id == self.agent_id:
            # Self-judgment: record what we did
            if donor_id == self.agent_id:
                self.my_last_actions.append(donor_action)
            if recipient_id == self.agent_id:
                self.my_last_actions.append(recipient_action)

        # Track opponent behavior if this agent is involved
        if donor_id == self.agent_id:
            opp = recipient_id
            action = recipient_action
        elif recipient_id == self.agent_id:
            opp = donor_id
            action = donor_action
        else:
            opp = None
            action = None

        if opp is not None:
            if opp not in self.opponent_history:
                self.opponent_history[opp] = []
            self.opponent_history[opp].append(action)
            if len(self.opponent_history[opp]) > 10:
                self.opponent_history[opp].pop(0)

        # Track who defected against us
        if donor_id == self.agent_id and recipient_action == 'defect':
            self.victim_of_defection.add(recipient_id)
        if recipient_id == self.agent_id and donor_action == 'defect':
            self.victim_of_defection.add(donor_id)

        # Track overall behavior
        if donor_action == 'cooperate':
            self.cooperators_seen.add(donor_id)
        else:
            self.defectors_seen.add(donor_id)
        if recipient_action == 'cooperate':
            self.cooperators_seen.add(recipient_id)
        else:
            self.defectors_seen.add(recipient_id)

    def _update_reputation(self, agent_id: int, action: str) -> None:
        """Update reputation score for an agent based on action."""
        if action == 'cooperate':
            # Increase reputation, but not too fast
            self.reputation[agent_id] = self.reputation.get(agent_id, 0.5) + 0.05
        else:
            # Decrease reputation
            self.reputation[agent_id] = self.reputation.get(agent_id, 0.5) - 0.1
        # Clamp reputation between 0 and 1
        self.reputation[agent_id] = max(0.0, min(1.0, self.reputation[agent_id]))

