class LLMAgent:
    def __init__(self, agent_id: int) -> None:
        self.agent_id = agent_id
        self.reputation = {}
        self.cooperation_count = {}
        self.defection_count = {}
        self.generation = 0
        self.round_num = 0
        self.observed_actions = {}
        self.my_cooperations = 0
        self.my_defections = 0
        self.last_action = None
        self.opponent_history = {}
        self.total_rounds = 0
        self.friendliness = 0.5
        self.trust = 0.5
        self.memory = []
        self.max_memory = 200

    def decide(self) -> bool:
        opponent_id = getattr(self, '_ctx_opponent_id', None)
        if opponent_id is None:
            return True

        # Update round number based on observed actions? We'll track in observe
        # Compute opponent reputation
        opp_rep = self.reputation.get(opponent_id, 0.5)
        opp_coop = self.cooperation_count.get(opponent_id, 0)
        opp_def = self.defection_count.get(opponent_id, 0)
        total_opp = opp_coop + opp_def

        # Personal history with this opponent
        hist = self.opponent_history.get(opponent_id, [])
        recent = hist[-3:] if hist else []

        # Simple strategy: cooperate if opponent has good reputation or we've cooperated with them recently
        if total_opp == 0:
            # Unknown opponent - be nice initially
            if self.my_defections > self.my_cooperations * 2:
                # If we've been defecting a lot, maybe cooperate to repair
                return True
            return True
        else:
            coop_ratio = opp_coop / total_opp
            # Punish defectors, reward cooperators
            if coop_ratio > 0.7:
                return True
            elif coop_ratio < 0.3:
                return False
            else:
                # Mixed - use recent history and randomness
                if recent:
                    last_opp_action = recent[-1][1]
                    if last_opp_action == 'defect':
                        # They defected last time - maybe defect back
                        if random.random() < 0.7:
                            return False
                        else:
                            return True
                    else:
                        return True
                else:
                    return True

    def observe(self, donor_id: int, donor_action: str, recipient_id: int, recipient_action: str) -> None:
        # Update counts for both donor and recipient
        if donor_action == 'cooperate':
            self.cooperation_count[donor_id] = self.cooperation_count.get(donor_id, 0) + 1
        else:
            self.defection_count[donor_id] = self.defection_count.get(donor_id, 0) + 1

        if recipient_action == 'cooperate':
            self.cooperation_count[recipient_id] = self.cooperation_count.get(recipient_id, 0) + 1
        else:
            self.defection_count[recipient_id] = self.defection_count.get(recipient_id, 0) + 1

        # Update reputations based on actions (more weight to cooperation)
        donor_rep_change = 0.1 if donor_action == 'cooperate' else -0.2
        recipient_rep_change = 0.05 if recipient_action == 'cooperate' else -0.1
        self.reputation[donor_id] = self.reputation.get(donor_id, 0.5) + donor_rep_change
        self.reputation[recipient_id] = self.reputation.get(recipient_id, 0.5) + recipient_rep_change

        # Clamp reputations to [0,1]
        for pid in [donor_id, recipient_id]:
            self.reputation[pid] = max(0.0, min(1.0, self.reputation[pid]))

        # Track opponent history if this involves us
        if donor_id == self.agent_id:
            self.my_cooperations += 1 if donor_action == 'cooperate' else 0
            self.my_defections += 1 if donor_action == 'defect' else 0
            self.opponent_history.setdefault(recipient_id, []).append((donor_action, recipient_action))
            # Keep history short
            if len(self.opponent_history[recipient_id]) > 10:
                self.opponent_history[recipient_id] = self.opponent_history[recipient_id][-10:]
        elif recipient_id == self.agent_id:
            self.my_cooperations += 1 if recipient_action == 'cooperate' else 0
            self.my_defections += 1 if recipient_action == 'defect' else 0
            self.opponent_history.setdefault(donor_id, []).append((recipient_action, donor_action))
            if len(self.opponent_history[donor_id]) > 10:
                self.opponent_history[donor_id] = self.opponent_history[donor_id][-10:]

        # Store observation in memory
        self.memory.append((donor_id, donor_action, recipient_id, recipient_action))
        if len(self.memory) > self.max_memory:
            self.memory = self.memory[-self.max_memory:]

        # Track observed actions for pattern detection (optional)
        key = (donor_id, recipient_id)
        if key not in self.observed_actions:
            self.observed_actions[key] = []
        self.observed_actions[key].append((donor_action, recipient_action))
        if len(self.observed_actions[key]) > 20:
            self.observed_actions[key] = self.observed_actions[key][-20:]

